Here is the commit message:
drm/amdgpu: fix JPEG instance checking when ctx init

Use proper structure.

Fixes: 0388aee766376ed ("drm/amdgpu: use the JPEG structure for general driver support")
Signed-off-by: Leo Liu <leo.liu@amd.com>
Reviewed-by: Alex Deucher <alexander.deucher@amd.com>
Reviewed-by: James Zhu <James.Zhu@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>

Here is the root cause:
The bug was caused by using the incorrect structure (`vcn`) to check the harvest configuration for JPEG instances instead of the correct structure (`jpeg`). This led to improper instance checking during context initialization, potentially resulting in incorrect behavior or failures when handling JPEG operations.

Here is the patch:

 static int amdgpu_ctx_init(struct amdgpu_device *adev,
 			   enum drm_sched_priority priority,
 			   struct drm_file *filp,
 			   struct amdgpu_ctx *ctx)
 {
 	unsigned num_entities = amdgpu_ctx_total_num_entities();
 	unsigned i, j, k;
 	int r;

 	if (priority < 0 || priority >= DRM_SCHED_PRIORITY_MAX)
 		return -EINVAL;

 	r = amdgpu_ctx_priority_permit(filp, priority);
 	if (r)
 		return r;

 	memset(ctx, 0, sizeof(*ctx));
 	ctx->adev = adev;

 	ctx->fences = kcalloc(amdgpu_sched_jobs * num_entities,
 			      sizeof(struct dma_fence*), GFP_KERNEL);
 	if (!ctx->fences)
 		return -ENOMEM;

 	ctx->entities[0] = kcalloc(num_entities,
 				   sizeof(struct amdgpu_ctx_entity),
 				   GFP_KERNEL);
 	if (!ctx->entities[0]) {
 		r = -ENOMEM;
 		goto error_free_fences;
 	}

 	for (i = 0; i < num_entities; ++i) {
 		struct amdgpu_ctx_entity *entity = &ctx->entities[0][i];

 		entity->sequence = 1;
 		entity->fences = &ctx->fences[amdgpu_sched_jobs * i];
 	}
 	for (i = 1; i < AMDGPU_HW_IP_NUM; ++i)
 		ctx->entities[i] = ctx->entities[i - 1] +
 			amdgpu_ctx_num_entities[i - 1];

 	kref_init(&ctx->refcount);
 	spin_lock_init(&ctx->ring_lock);
 	mutex_init(&ctx->lock);

 	ctx->reset_counter = atomic_read(&adev->gpu_reset_counter);
 	ctx->reset_counter_query = ctx->reset_counter;
 	ctx->vram_lost_counter = atomic_read(&adev->vram_lost_counter);
 	ctx->init_priority = priority;
 	ctx->override_priority = DRM_SCHED_PRIORITY_UNSET;

 	for (i = 0; i < AMDGPU_HW_IP_NUM; ++i) {
 		struct amdgpu_ring *rings[AMDGPU_MAX_RINGS];
 		struct drm_sched_rq *rqs[AMDGPU_MAX_RINGS];
 		unsigned num_rings = 0;
 		unsigned num_rqs = 0;

 		switch (i) {
 		case AMDGPU_HW_IP_GFX:
 			rings[0] = &adev->gfx.gfx_ring[0];
 			num_rings = 1;
 			break;
 		case AMDGPU_HW_IP_COMPUTE:
 			for (j = 0; j < adev->gfx.num_compute_rings; ++j)
 				rings[j] = &adev->gfx.compute_ring[j];
 			num_rings = adev->gfx.num_compute_rings;
 			break;
 		case AMDGPU_HW_IP_DMA:
 			for (j = 0; j < adev->sdma.num_instances; ++j)
 				rings[j] = &adev->sdma.instance[j].ring;
 			num_rings = adev->sdma.num_instances;
 			break;
 		case AMDGPU_HW_IP_UVD:
 			rings[0] = &adev->uvd.inst[0].ring;
 			num_rings = 1;
 			break;
 		case AMDGPU_HW_IP_VCE:
 			rings[0] = &adev->vce.ring[0];
 			num_rings = 1;
 			break;
 		case AMDGPU_HW_IP_UVD_ENC:
 			rings[0] = &adev->uvd.inst[0].ring_enc[0];
 			num_rings = 1;
 			break;
 		case AMDGPU_HW_IP_VCN_DEC:
 			for (j = 0; j < adev->vcn.num_vcn_inst; ++j) {
 				if (adev->vcn.harvest_config & (1 << j))
 					continue;
 				rings[num_rings++] = &adev->vcn.inst[j].ring_dec;
 			}
 			break;
 		case AMDGPU_HW_IP_VCN_ENC:
 			for (j = 0; j < adev->vcn.num_vcn_inst; ++j) {
 				if (adev->vcn.harvest_config & (1 << j))
 					continue;
 				for (k = 0; k < adev->vcn.num_enc_rings; ++k)
 					rings[num_rings++] = &adev->vcn.inst[j].ring_enc[k];
 			}
 			break;
 		case AMDGPU_HW_IP_VCN_JPEG:
 			for (j = 0; j < adev->jpeg.num_jpeg_inst; ++j) {
-				if (adev->vcn.harvest_config & (1 << j))
+				if (adev->jpeg.harvest_config & (1 << j))
 					continue;
 				rings[num_rings++] = &adev->jpeg.inst[j].ring_dec;
 			}
 			break;
 		}

 		for (j = 0; j < num_rings; ++j) {
 			if (!rings[j]->adev)
 				continue;

 			rqs[num_rqs++] = &rings[j]->sched.sched_rq[priority];
 		}

 		for (j = 0; j < amdgpu_ctx_num_entities[i]; ++j)
 			r = drm_sched_entity_init(&ctx->entities[i][j].entity,
 						  rqs, num_rqs, &ctx->guilty);
 		if (r)
 			goto error_cleanup_entities;
 	}

 	return 0;

 error_cleanup_entities:
 	for (i = 0; i < num_entities; ++i)
 		drm_sched_entity_destroy(&ctx->entities[0][i].entity);
 	kfree(ctx->entities[0]);

 error_free_fences:
 	kfree(ctx->fences);
 	ctx->fences = NULL;
 	return r;
 }



